mapper.select:
/** * selectIcbtgConsttChcList : isry.couns.mngr.icbtgmng.mapper.IcbtgConsttChcMapper : 인큐베이팅 상담자선택 조회 */ SELECT AA.USER_ID AS USER_ID , AA.WORK_YMD AS WORK_YMD , C##RG.DEC_B64(DD.FLNM_ENCPT) AS USER_NM , FF.DEPT_NM AS DEPT_NM , NVL(BB.NTABRD_USE_YN,'N') AS NTABRD_USE_YN /** 게시판사용여부 **/ , NVL(BB.FLAG_YN,'N') AS FLAG_YN /** 플래그여부 **/ FROM AYC100 AA /** 근무배정표_일별 **/ , AYC150 BB /** 근무배정표_인큐베이팅 **/ , SAA200 CC /** 기관사용자 **/ , SCA100 DD /** 종사자 **/ , SCA140 EE /** 종사자수행업무 **/ , SAA300 FF /** 기관부서 **/ WHERE 1=1 AND AA.USER_ID = BB.CONSTT_ID(+) AND AA.USER_ID = CC.USER_ID AND CC.ENFSN_NO = DD.ENFSN_NO AND DD.ENFSN_NO = EE.ENFSN_NO AND EE.OGDP_DEPT_CD = FF.DEPT_CD
AND AA.WORK_YMD = #{workYmd}
AND EE.OGDP_DEPT_CD = #{deptCd}
